} function loadTTSFile(){ ttsButtonStatus("loading"); if($("#tts_file").val()=="" || $("#tts_file").val()=="undefined"){ $.ajax({ type: "GET", url: "/news/getTTSAjax.php?articleId="+articleId, dataType: "jsonp", success:function(result){ var tmpFile=result.content; $("#tts_file").val(tmpFile); //alert(tmpFile + " 로딩완료"); playTTS(); }, timeout: 1000*120, error:function(){ alert("데이터 수신에 실패 하였습니다."); } }); }else{ playTTS(); } } 서울시의회 더불어민주당이 20일 직무유기, 권한 남용, 의정활동 방해 등의 이유로 ‘서울시의회 의장 최호정 불신임의 건’을 제출하며 다음과 같이 논평을 냈다.다음은 서울시의회 더불어민주당 박수빈 대변인 논평 전문서울시의회 더불어민주당(대표의원 성흠제)은 20일 ‘서울시의회 의장 최호정 불신임의 건’을 제출했다. 이번 불신임안은 최호정 의장이 행한 직무유기, 회의규칙 위반, 자의적 의사일정 운영, 의원 권한 침해 등 명백한 위법 행위에 근거한 불가피한 조치이다.최 의장은 지난 10월 31일 전임 문화체육관광위원장 사임 이후 정당한 사유없이 보궐 선출을 두 차례나 보류하며 상임위원회를 부위원장 체제로 방치했다. 제333회 정례회가 행정사무감사와 내년도 예산안 심사가 동시에 진행되는 연중 가장 중요한 회기임에도 위원장 부재 상태를 장기간 지속시켜 위원회의 정상적 기능을 사실상 마비시켰다. 이는 ‘지방자치법’ 제62조가 규정하는 ‘정당한 사유 없이 직무를 수행하지 아니한 경우’인 명백한 직무유기이다.최 의장은 11월 3일 ‘서울시의회 문화체육관광위원장 보궐선거의 건’을 상정했다가 해당 안건을 처리할 순서가 되자 독단적으로 보류했다. 이는 ‘서울시의회 기본 조례’및 ‘서울시의회 회의규칙’이 정한 의사일정 변경 절차를 무시한 것이다. 회의규칙은 의원 10명 이상의 연서동의에 따른 본회의 의결이 있거나, 양당 대표의원과 협의가 있을 때 의사일정 변경을 허용하고 있음에도 불구하고 의장은 어떠한 절차도 거치지 않고 일방적으로 상정 보류를 결정했다. 그 과정에서 양당 대표의원과 충분한 협의가 이뤄지지 않았다.또한 20일 최 의장은 ‘서울시의회 문화체육관광위원장 보궐선거의 건’을 재상정했으나 국민의힘 이종배 의원의 신상발언을 핑계로 정회 요청도 묵살하고 또다시 보류를 의결했다. 과거에도 최 의장의 직무유기와 의정활동 침해는 빈번했다. 최 의장은 지난 4월 열린 제330회 임시회에서 예정되어 있던 시정질문을 일방적으로 취소했다. ‘서울시의회 기본 조례’ 제50조제2항의 ‘교섭단체 소속 의원 수의 비율에 따른 배분’ 규정을 자의적으로 왜곡·악용하여 국민의힘 소속의원들이 질문을 취소했다는 이유로 더불어민주당 의원의 질문권까지 박탈했다. 제출된 시정질문 요지서를 기한 내에 집행부에 송부하지 않으며 의장의 행정적 직무를 방기하기도 했다. 이 또한 ‘지방자치법’ 제62조가 규정한 법령위반, 직무유기에 해당하는 의장 불신임 사유이다.최 의장은 의회의 대표로서 누구보다 엄격하게 지켜야 할 법령과 절차를 반복적으로 훼손했다. 정치적 이해와 사적 판단에 따른 ‘묻지마식 의회운영’으로 의정활동의 공정성을 침해하고, 의원의 권리를 제약했다. 의장 스스로 서울시의회의 위상과 의회민주주의의 기본 질서를 무너뜨린 중대한 사안이 아닐 수 없다.서울시의회 더불어민주당은 더 이상 이러한 파행 운영과 절차 파괴를 묵과할 수 없다. 이에 ‘지방자치법’, ‘서울시의회 기본 조례’, ‘서울시의회 회의규칙’ 위반에 따른 불가피하고 정당한 조치로서 최호정 의장 불신임을 결의하며, 의회민주주의 회복과 의회운영의 정상화를 위해 단호히 대응할 것임을 천명한다.서울시의회 더불어민주당 대변인 박수빈온라인뉴스팀 Copyright ⓒ